1	package tui
2	
3	import (
4		"strings"
5	
6		tea "github.com/charmbracelet/bubbletea"
7		"github.com/charmbracelet/bubbles/viewport"
8		"github.com/charmbracelet/lipgloss"
9	
10		"github.com/immuta/operations/apps/birdseye/internal/diff"
11	)
12	
13	// Browser is the multi-pane diff viewer: file tree on the left,
14	// rendered unified diff on the right, footer at the bottom.
15	type Browser struct {
16		result   diff.Result
17		theme    Theme
18		selected int
19		width    int
20		height   int
21		viewport viewport.Model
22	}
23	
24	// NewBrowser builds a Browser from a pre-computed Result. SetSize must
25	// be called once before the first View() so the viewport sizes itself.
26	func NewBrowser(r diff.Result) *Browser {
27		vp := viewport.New(0, 0)
28		return &Browser{
29			result:   r,
30			theme:    DefaultTheme(),
31			viewport: vp,
32		}
33	}
34	
35	// SetSize informs the browser of the terminal dimensions.
36	func (b *Browser) SetSize(w, h int) {
37		b.width, b.height = w, h
38		fileTreeW := 32
39		if w < 80 {
40			fileTreeW = 24
41		}
42		contentW := w - fileTreeW - 4
43		contentH := h - 2
44		if contentW < 10 {
45			contentW = 10
46		}
47		if contentH < 5 {
48			contentH = 5
49		}
50		b.viewport.Width = contentW
51		b.viewport.Height = contentH
52		b.refreshViewport()
53	}
54	
55	// SelectedIndex returns the currently focused file diff index.
56	func (b *Browser) SelectedIndex() int { return b.selected }
57	
58	// SelectedFile returns the FileDiff at the current selection. Falls
59	// back to a zero value when the result has no files.
60	func (b *Browser) SelectedFile() diff.FileDiff {
61		if len(b.result.Files) == 0 {
62			return diff.FileDiff{}
63		}
64		return b.result.Files[b.selected]
65	}
66	
67	// Move adjusts the selection by delta, clamping to the valid range, and
68	// refreshes the viewport content.
69	func (b *Browser) Move(delta int) {
70		if len(b.result.Files) == 0 {
71			return
72		}
73		b.selected += delta
74		if b.selected < 0 {
75			b.selected = 0
76		}
77		if b.selected >= len(b.result.Files) {
78			b.selected = len(b.result.Files) - 1
79		}
80		b.refreshViewport()
81	}
82	
83	func (b *Browser) refreshViewport() {
84		if len(b.result.Files) == 0 {
85			b.viewport.SetContent("no differences")
86			return
87		}
88		b.viewport.SetContent(b.colorizeUnified(b.SelectedFile().Unified))
89		b.viewport.GotoTop()
90	}
91	
92	func (b *Browser) colorizeUnified(unified string) string {
93		var sb strings.Builder
94		for _, line := range strings.Split(unified, "\n") {
95			switch {
96			case strings.HasPrefix(line, "@@"):
97				sb.WriteString(b.theme.HunkHeader.Render(line))
98			case strings.HasPrefix(line, "+") && !strings.HasPrefix(line, "+++"):
99				sb.WriteString(b.theme.AddedLine.Render(line))
100			case strings.HasPrefix(line, "-") && !strings.HasPrefix(line, "---"):
101				sb.WriteString(b.theme.RemovedLine.Render(line))
102			default:
103				sb.WriteString(line)
104			}
105			sb.WriteByte('\n')
106		}
107		return sb.String()
108	}
109	
110	// Init satisfies tea.Model. No initial cmd — browser is purely reactive.
111	func (b *Browser) Init() tea.Cmd { return nil }
112	
113	// Update handles key presses and window-resize messages.
114	func (b *Browser) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
115		switch msg := msg.(type) {
116		case tea.WindowSizeMsg:
117			b.SetSize(msg.Width, msg.Height)
118			return b, nil
119		case tea.KeyMsg:
120			switch msg.Type {
121			case tea.KeyDown:
122				b.Move(1)
123				return b, nil
124			case tea.KeyUp:
125				b.Move(-1)
126				return b, nil
127			case tea.KeyRunes:
128				switch string(msg.Runes) {
129				case "q":
130					return b, tea.Quit
131				case "j":
132					b.Move(1)
133				case "k":
134					b.Move(-1)
135				}
136			}
137		}
138		// Forward to viewport for scroll handling.
139		var cmd tea.Cmd
140		b.viewport, cmd = b.viewport.Update(msg)
141		return b, cmd
142	}
143	
144	// View renders the full multi-pane layout.
145	func (b *Browser) View() string {
146		tree := b.renderTree()
147		right := b.theme.Viewport.Render(b.viewport.View())
148		body := lipgloss.JoinHorizontal(lipgloss.Top, tree, right)
149		footer := b.theme.Footer.Render("j/k or ↑/↓ move · q quit · esc back")
150		return lipgloss.JoinVertical(lipgloss.Left, body, footer)
151	}
152	
153	func (b *Browser) renderTree() string {
154		var sb strings.Builder
155		for i, fd := range b.result.Files {
156			marker := " "
157			switch fd.Status {
158			case diff.StatusAdded:
159				marker = b.theme.StatusAdd.Render("+")
160			case diff.StatusRemoved:
161				marker = b.theme.StatusDel.Render("-")
162			case diff.StatusModified:
163				marker = b.theme.StatusMod.Render("~")
164			}
165			line := marker + " " + fd.Path
166			if i == b.selected {
167				line = b.theme.FileSelected.Render(line)
168			} else {
169				line = b.theme.FileTreeItem.Render(line)
170			}
171			sb.WriteString(line)
172			sb.WriteByte('\n')
173		}
174		if len(b.result.Files) == 0 {
175			sb.WriteString("(no files)")
176		}
177		return b.theme.FileTree.Render(sb.String())
178	}
