1	package tui
2	
3	import (
4		"testing"
5	
6		tea "github.com/charmbracelet/bubbletea"
7	
8		"github.com/immuta/operations/apps/birdseye/internal/diff"
9	)
10	
11	func sampleResult() diff.Result {
12		return diff.Result{Files: []diff.FileDiff{
13			{Path: "a.tf", Status: diff.StatusModified, Unified: "@@\n-x\n+y\n", Adds: 1, Dels: 1},
14			{Path: "b.tf", Status: diff.StatusAdded, Unified: "+++ b.tf\n+new\n", Adds: 1},
15		}}
16	}
17	
18	func TestNewBrowserDefaults(t *testing.T) {
19		b := NewBrowser(sampleResult())
20		if b.SelectedIndex() != 0 {
21			t.Errorf("default selected index = %d, want 0", b.SelectedIndex())
22		}
23		if b.SelectedFile().Path != "a.tf" {
24			t.Errorf("first selected = %s", b.SelectedFile().Path)
25		}
26	}
27	
28	func TestBrowserViewContainsBothFiles(t *testing.T) {
29		b := NewBrowser(sampleResult())
30		b.SetSize(120, 30)
31		view := b.View()
32		for _, want := range []string{"a.tf", "b.tf"} {
33			if !contains(view, want) {
34				t.Errorf("view missing %q\n%s", want, view)
35			}
36		}
37	}
38	
39	func contains(s, sub string) bool {
40		for i := 0; i+len(sub) <= len(s); i++ {
41			if s[i:i+len(sub)] == sub {
42				return true
43			}
44		}
45		return false
46	}
47	
48	func TestBrowserMovesDownAndUp(t *testing.T) {
49		b := NewBrowser(sampleResult())
50		b.SetSize(120, 30)
51		m, _ := b.Update(tea.KeyMsg{Type: tea.KeyDown})
52		b2 := m.(*Browser)
53		if b2.SelectedIndex() != 1 {
54			t.Errorf("after down: index = %d, want 1", b2.SelectedIndex())
55		}
56		m, _ = b2.Update(tea.KeyMsg{Type: tea.KeyUp})
57		b3 := m.(*Browser)
58		if b3.SelectedIndex() != 0 {
59			t.Errorf("after up: index = %d, want 0", b3.SelectedIndex())
60		}
61	}
62	
63	func TestBrowserQuitMessage(t *testing.T) {
64		b := NewBrowser(sampleResult())
65		b.SetSize(120, 30)
66		_, cmd := b.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'q'}})
67		if cmd == nil {
68			t.Fatal("expected tea.Quit cmd")
69		}
70		if got, want := cmd(), tea.Quit(); got != want {
71			t.Errorf("cmd msg = %v, want %v", got, want)
72		}
73	}
